selector_to_html = {"a[href=\"architecture/profiler.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Profiler \u96c6\u6210<a class=\"headerlink\" href=\"#profiler\" title=\"Link to this heading\">#</a></h1><p><code class=\"docutils literal notranslate\"><span class=\"pre\">torch.profiler</span></code> \u901a\u8fc7\u7f16\u8bd1\u8fdb wheel \u7684\u8bbe\u5907\u8ffd\u8e2a\u5668\u652f\u6301 <code class=\"docutils literal notranslate\"><span class=\"pre\">flagos</span></code> \u8bbe\u5907\u3002<code class=\"docutils literal notranslate\"><span class=\"pre\">torch.profiler.profile(activities=[CPU,</span> <span class=\"pre\">PrivateUse1])</span></code> \u4ea7\u51fa\u7684 trace \u4e0e\u540c\u4e00\u5de5\u4f5c\u8d1f\u8f7d\u5728 <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.cuda</span></code> \u4e0a\u7684 trace \u7ed3\u6784\u7b49\u4ef7\uff1a</p>", "a[href=\"reference/compatibility.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u517c\u5bb9\u6027\u4e0e\u5e73\u53f0\u652f\u6301<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><h2>\u72b6\u6001\u5b9a\u4e49<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#torch-fl\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Torch-FL<a class=\"headerlink\" href=\"#torch-fl\" title=\"Link to this heading\">#</a></h1><p>Torch-FL\uff08<code class=\"docutils literal notranslate\"><span class=\"pre\">torch_fl</span></code>\uff09\u662f\u9762\u5411 FlagOS \u8f6f\u4ef6\u6808\u7684 PyTorch \u8bbe\u5907\u63d2\u4ef6\u3002\u5b83\u5bf9\u5916\u63d0\u4f9b\u7edf\u4e00\u7684 <code class=\"docutils literal notranslate\"><span class=\"pre\">flagos</span></code> \u8bbe\u5907\uff0c\u5e76\u5728\u53ef\u590d\u7528\u539f\u751f\u5185\u6838\u3001\u53ef\u79fb\u690d\u7f16\u8bd1\u5668\u5185\u6838\u3001\u5382\u5546\u539f\u751f\u5b9e\u73b0\u548c\u663e\u5f0f CPU \u56de\u9000\u4e4b\u95f4\u8def\u7531\u7b97\u5b50\uff0c\u4f7f\u540c\u4e00\u4efd PyTorch \u7a0b\u5e8f\u65e0\u9700\u4fee\u6539\u5373\u53ef\u8fd0\u884c\u5728\u4e0d\u540c\u52a0\u901f\u5668\u4e0a\u3002</p><p><a data-lightbox=\"image-set\" href=\"_images/torch-fl.png\">\n<img alt=\"Torch-FL \u67b6\u6784\" src=\"_images/torch-fl.png\"/></a>\n</p>", "a[href=\"overview/overview.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Torch-FL \u6982\u89c8<a class=\"headerlink\" href=\"#torch-fl\" title=\"Link to this heading\">#</a></h1><p><code class=\"docutils literal notranslate\"><span class=\"pre\">torch_fl</span></code> \u662f\u57fa\u4e8e <code class=\"docutils literal notranslate\"><span class=\"pre\">PrivateUse1</span></code> \u6269\u5c55\u673a\u5236\u7684\u81ea\u5b9a\u4e49 PyTorch \u8bbe\u5907\u63d2\u4ef6\u3002\u5b83\u5c06 <a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagGems\">FlagGems</a> \u9ad8\u6027\u80fd Triton \u7b97\u5b50\u3001\u5382\u5546\u539f\u751f\u7b97\u5b50\u5e93\u548c CUDA \u517c\u5bb9\u5185\u6838\u7edf\u4e00\u6ce8\u518c\u5230\u540c\u4e00\u4e2a\u8bbe\u5907\u540d\u79f0\u4e0b\uff1a<code class=\"docutils literal notranslate\"><span class=\"pre\">flagos</span></code>\u3002</p><p>\u4e0d\u540c\u52a0\u901f\u5668\u5382\u5546\u63d0\u4f9b\u7684\u8fd0\u884c\u65f6\u3001\u7f16\u8bd1\u5668\u6808\u548c PyTorch \u96c6\u6210\u65b9\u5f0f\u5404\u4e0d\u76f8\u540c\u3002Torch-FL \u901a\u8fc7\u7edf\u4e00\u7684\u8fd0\u884c\u65f6\u548c\u7b97\u5b50\u8def\u7531\u5c42\u5c4f\u853d\u8fd9\u4e9b\u5dee\u5f02\uff1a\u7528\u6237\u53ea\u4f7f\u7528\u6807\u51c6 PyTorch API \u548c\u5355\u4e00\u8bbe\u5907\u540d\u79f0\uff0c\u63d2\u4ef6\u6839\u636e\u5e73\u53f0\u80fd\u529b\u4e0e\u914d\u7f6e\u4e3a\u6bcf\u4e2a\u7b97\u5b50\u9009\u62e9\u5185\u6838\u5b9e\u73b0\u3002</p>", "a[href=\"architecture/distributed.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u5206\u5e03\u5f0f\u96c6\u5408\u901a\u4fe1<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><p>Torch-FL \u901a\u8fc7 <code class=\"docutils literal notranslate\"><span class=\"pre\">ProcessGroupFlagOS</span></code> \u4e3a <code class=\"docutils literal notranslate\"><span class=\"pre\">flagos</span></code> \u8bbe\u5907\u63d0\u4f9b\u5206\u5e03\u5f0f\u652f\u6301\u3002\u5b83\u662f\u539f\u751f\u7684 <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.distributed.ProcessGroup</span></code> \u5b50\u7c7b\uff0c\u5728\u5bfc\u5165\u65f6\u5b8c\u6210\u6ce8\u518c\uff0c\u56e0\u6b64 <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.distributed.init_process_group(\"flagos\")</span></code> \u53ef\u76f4\u63a5\u4f7f\u7528\uff0c\u65e0\u9700\u5bf9 <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.distributed.*</span></code> \u505a\u4efb\u4f55 monkeypatch\u3002</p>", "a[href=\"getting_started/installation.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u5b89\u88c5<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><h2>\u9009\u62e9\u5e73\u53f0<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h2><p>\u6bcf\u4e2a\u5e73\u53f0\u7531\u4e00\u4e2a\u6784\u5efa\u53d8\u91cf <code class=\"docutils literal notranslate\"><span class=\"pre\">FLAGOS_ACCELERATOR</span></code> \u9009\u62e9\uff0c\u5e76\u4e14\u5404\u81ea\u6709\u72ec\u7acb\u7684\u6267\u884c\u8def\u5f84\uff1a</p>", "a[href=\"architecture/torch-compile.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">torch.compile \u96c6\u6210<a class=\"headerlink\" href=\"#torch-compile\" title=\"Link to this heading\">#</a></h1><p><code class=\"docutils literal notranslate\"><span class=\"pre\">flagos</span></code> \u8bbe\u5907\u652f\u6301 <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.compile</span></code>\uff0c\u53ef\u5b9e\u73b0\u81ea\u52a8\u5185\u6838\u878d\u5408\u5e76\u964d\u4f4e\u8c03\u5ea6\u5f00\u9500\u3002\u8ba1\u7b97\u56fe\u59cb\u7ec8\u7559\u5728 <code class=\"docutils literal notranslate\"><span class=\"pre\">flagos</span></code> \u8bbe\u5907\u4e0a\uff1a\u4e0d\u5b58\u5728\u8bbe\u5907\u5f80\u8fd4\uff0c\u4e5f\u6ca1\u6709\u56fe\u8fb9\u754c\u5904\u7684\u62f7\u8d1d\u3002</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
